24|// Per-row sum: walk row by row. Each row is contiguous in memory so the
25|// access pattern is good. This is the obvious "right" way to do it.
26|std::vector<double> Matrix::SumPerRow() const {
27|    std::vector<double> result(rows_, 0.0);
28|    for (std::size_t r = 0; r < rows_; ++r) {
29|        double s = 0.0;
30|        for (std::size_t c = 0; c < cols_; ++c) {
31|            s += at(r, c);
32|        }
33|        result[r] = s;
34|    }
35|    return result;
36|}
37|
38|// Per-column sum: walk column by column. Each access is (data_[0 * cols + c],
39|// data_[1 * cols + c], ...). The stride between accesses is `cols` doubles,
40|// which is much larger than a typical cache line (64 bytes / 8 doubles).
41|// On a 1024x1024 matrix this strides by 8KB per access, blowing the L1
42|// cache on every load. This is the slow path callers complain about.
43|std::vector<double> Matrix::SumPerColumn() const {
44|    std::vector<double> result(cols_, 0.0);
45|    for (std::size_t c = 0; c < cols_; ++c) {
46|        double s = 0.0;
47|        for (std::size_t r = 0; r < rows_; ++r) {
48|            s += at(r, c);
49|        }
50|        result[c] = s;
51|    }
52|    return result;
53|}
54|
55|// In-place transpose of a square matrix. We swap at(i, j) with at(j, i)
56|// for the upper triangle. The row-major layout means at(i, j) reads
57|// `cols_` elements ahead of the previous read - on a wide matrix that
58|// thrashes the cache. Faster implementations do a block transpose.
59|void TransposeSquare(Matrix& m) {
60|    if (m.rows() != m.cols()) {
61|        throw std::invalid_argument("TransposeSquare requires a square matrix");
62|    }
63|    const std::size_t n = m.rows();
64|    for (std::size_t i = 0; i < n; ++i) {
65|        for (std::size_t j = i + 1; j < n; ++j) {
66|            const double tmp = m.at(i, j);
67|            m.at(i, j) = m.at(j, i);
68|            m.at(j, i) = tmp;
69|        }
70|    }
